contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory tos, uint[] memory vals) public {
        require(tos.length > 0);
        require(tos.length == vals.length);
        address before = c.caddress();
        bool reverted;
        try c.transfer(tos, vals) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.caddress() == before && address(c).balance == 0);
    }
    receive() external payable {}
}

